import React, { useState, useEffect } from 'react';
import { useSearchParams, Link } from 'react-router-dom';
import { useAuth } from '../context/AuthContext';
import api from '../services/api';
import ProductCard from '../components/ProductCard';
import ProductModal from '../components/ProductModal';
import { FiSearch } from 'react-icons/fi';

const Home = () => {
    const { user } = useAuth();
    const [searchParams, setSearchParams] = useSearchParams();
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const [category, setCategory] = useState('todos');
    const [selectedProduct, setSelectedProduct] = useState(null);
    const [modalOpen, setModalOpen] = useState(false);
    const [searchTerm, setSearchTerm] = useState(searchParams.get('search') || '');

    useEffect(() => {
        fetchProducts();
    }, [category, searchParams]);

    const fetchProducts = async () => {
        setLoading(true);
        try {
            const search = searchParams.get('search') || '';
            const response = await api.get('/products', {
                params: { category: category !== 'todos' ? category : undefined, search, limit: 12 }
            });
            setProducts(response.data.products);
        } catch (error) {
            console.error('Erro ao buscar produtos:', error);
        } finally {
            setLoading(false);
        }
    };

    const handleSearch = (e) => {
        e.preventDefault();
        if (searchTerm.trim()) {
            setSearchParams({ search: searchTerm });
        } else {
            setSearchParams({});
        }
    };

    const openModal = (product) => {
        setSelectedProduct(product);
        setModalOpen(true);
    };

    const closeModal = () => {
        setModalOpen(false);
        setSelectedProduct(null);
    };

    useEffect(() => {
        const handleOpenModal = (event) => {
            if (event.detail) {
                openModal(event.detail);
            }
        };
        
        window.addEventListener('openProductModal', handleOpenModal);
        
        return () => {
            window.removeEventListener('openProductModal', handleOpenModal);
        };
    }, []);

    const categories = [
        { id: 'todos', name: 'Todos', icon: '📦', color: 'bg-gray-100 dark:bg-gray-700 text-gray-700 dark:text-gray-300' },
        { id: 'telemovel', name: 'Telemóveis', icon: '📱', color: 'bg-blue-50 dark:bg-blue-900/30 text-blue-700 dark:text-blue-300' },
        { id: 'laptop', name: 'Laptops', icon: '💻', color: 'bg-purple-50 dark:bg-purple-900/30 text-purple-700 dark:text-purple-300' },
        { id: 'tablet', name: 'Tablets', icon: '📟', color: 'bg-green-50 dark:bg-green-900/30 text-green-700 dark:text-green-300' },
        { id: 'console', name: 'Consoles', icon: '🎮', color: 'bg-red-50 dark:bg-red-900/30 text-red-700 dark:text-red-300' },
        { id: 'smartwatch', name: 'Smartwatches', icon: '⌚', color: 'bg-cyan-50 dark:bg-cyan-900/30 text-cyan-700 dark:text-cyan-300' },
        { id: 'audio', name: 'Áudio', icon: '🎧', color: 'bg-amber-50 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300' },
        { id: 'acessorios', name: 'Acessórios', icon: '🔌', color: 'bg-indigo-50 dark:bg-indigo-900/30 text-indigo-700 dark:text-indigo-300' },
    ];

    return (
        <div>
            {/* Hero Section */}
            <div className="bg-gradient-to-r from-blue-600 to-indigo-600 text-white rounded-2xl p-8 mb-8 text-center dark:from-gray-800 dark:to-gray-900">
                <h1 className="text-3xl md:text-4xl font-bold mb-4">InterConectados</h1>
                <p className="text-lg md:text-xl mb-6 opacity-90">Conectando pessoas através da tecnologia</p>
                {!user && (
                    <div className="flex justify-center gap-4">
                        <Link to="/register" className="bg-white text-blue-600 px-6 py-3 rounded-lg font-semibold hover:bg-gray-100 transition dark:bg-gray-800 dark:text-white dark:hover:bg-gray-700">
                            Começar a Comprar
                        </Link>
                        <Link to="/register" className="border-2 border-white text-white px-6 py-3 rounded-lg font-semibold hover:bg-white hover:text-blue-600 transition dark:border-gray-600 dark:hover:bg-gray-800">
                            Anunciar Grátis
                        </Link>
                    </div>
                )}
            </div>

            {/* Barra de Pesquisa Melhorada */}
            <div className="mb-8">
                <form onSubmit={handleSearch} className="relative max-w-2xl mx-auto">
                    <input
                        type="text"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                        placeholder="Buscar produtos por nome, marca ou descrição..."
                        className="w-full px-5 py-4 pl-12 pr-24 rounded-xl border border-gray-200 dark:border-gray-700 bg-white dark:bg-gray-800 text-gray-800 dark:text-gray-200 focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition shadow-sm"
                    />
                    <FiSearch className="absolute left-4 top-1/2 transform -translate-y-1/2 text-gray-400 dark:text-gray-500" size={20} />
                    <button
                        type="submit"
                        className="absolute right-2 top-1/2 transform -translate-y-1/2 bg-blue-600 hover:bg-blue-700 text-white px-5 py-2 rounded-lg transition font-medium"
                    >
                        Buscar
                    </button>
                </form>
            </div>

            {/* Categorias Melhoradas */}
            <div className="mb-8">
                <h3 className="text-sm font-medium text-gray-500 dark:text-gray-400 mb-3 uppercase tracking-wide">Categorias</h3>
                <div className="flex flex-wrap gap-3">
                    {categories.map(cat => (
                        <button
                            key={cat.id}
                            onClick={() => setCategory(cat.id)}
                            className={`px-5 py-2.5 rounded-full flex items-center gap-2 transition-all duration-200 ${
                                category === cat.id
                                    ? `${cat.color} ring-2 ring-offset-2 ring-blue-500 dark:ring-offset-gray-900`
                                    : 'bg-gray-100 dark:bg-gray-700 text-gray-600 dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-gray-600'
                            }`}
                        >
                            <span className="text-lg">{cat.icon}</span>
                            <span className="font-medium">{cat.name}</span>
                            {category === cat.id && (
                                <span className="ml-1 w-1.5 h-1.5 bg-current rounded-full"></span>
                            )}
                        </button>
                    ))}
                </div>
            </div>

            {/* Produtos */}
            <div className="flex justify-between items-center mb-4">
                <h2 className="text-2xl font-bold text-gray-800 dark:text-gray-200">Últimos Anúncios</h2>
                {searchParams.get('search') && (
                    <button
                        onClick={() => {
                            setSearchTerm('');
                            setSearchParams({});
                        }}
                        className="text-sm text-blue-600 dark:text-blue-400 hover:underline"
                    >
                        Limpar busca
                    </button>
                )}
            </div>
            
            {loading ? (
                <div className="flex justify-center py-12">
                    <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 dark:border-blue-400"></div>
                </div>
            ) : products.length === 0 ? (
                <div className="bg-white dark:bg-gray-800 rounded-xl p-12 text-center shadow">
                    <p className="text-gray-500 dark:text-gray-400">Nenhum produto encontrado.</p>
                    {searchParams.get('search') && (
                        <p className="text-sm text-gray-400 dark:text-gray-500 mt-2">
                            Tente buscar com outras palavras ou <button onClick={() => { setSearchTerm(''); setSearchParams({}); }} className="text-blue-600 dark:text-blue-400 hover:underline">limpar a busca</button>
                        </p>
                    )}
                </div>
            ) : (
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-6">
                    {products.map(product => (
                        <ProductCard 
                            key={product.id} 
                            product={product} 
                            onClick={() => openModal(product)}
                        />
                    ))}
                </div>
            )}

            {/* Modal de detalhes do produto */}
            <ProductModal 
                product={selectedProduct}
                isOpen={modalOpen}
                onClose={closeModal}
            />
        </div>
    );
};

export default Home;
